public function onComboItemSet(param1:ListEvent) : void
{
   param1.item.mc_label.txt_label.text = this._opts[param1.list.id].options[param1.index];
}

   if(this._opts[param1.index].options is Array)
   {
      param1.item.gotoAndStop(GenericOptionMenu.COMBO);
      param1.item.combo.id = param1.index;
      param1.item.combo.optionID = this._opts[param1.index].id;
      param1.item.combo.addEventListener(ListEvent.ITEM_SET,this.onComboItemSet);
      param1.item.combo.initValues(this._opts[param1.index].value,this._opts[param1.index].options.length);
      // AutoSave's constructor listener runs before this refresh listener.
      param1.item.combo.addEventListener(UIEvent.CHANGE,this.onComboValueChange,false,-1);
   }
   else
   {
      param1.item.gotoAndStop(GenericOptionMenu.SWITCH);
      param1.item.myOnOffSwitch.setInitValue(this._opts[param1.index].value);
      param1.item.myOnOffSwitch.optionID = this._opts[param1.index].id;
   }
   param1.item.infos_btn.visible = this._opts[param1.index].id < 200;
   if(this._graphicsRefreshing || this._graphicsStart < 0 || param1.previousValue == -1)
   {
      return;
   }
   // Custom is a derived caption, not a fifth selectable preset.
   if(param1.currentTarget.optionID == "200" && param1.value == 4 && param1.previousValue != 4)
   {
      param1.currentTarget.displayList(param1.previousValue == 3 ? 0 : 3,true);
      return;
   }
   var state:uint = this.graphicsState();
   var i:int = 0;
   while(i < 6)
   {
      this._opts[this._graphicsStart + i].value = state >>> (i * 3) & 7;
      i++;
   }
   this._graphicsRefreshing = true;
   this.options_list.refreshCurrent();
   this._graphicsRefreshing = false;
}

public static function NativeGraphicsState() : uint
{
   // Unbound native/failed backend leaves the original settings intact.
   return 0;
}

private function graphicsState() : uint
{
   // Object lookup follows gameswf's registered builtin map by name.
   var api:Object = MenuAdvanced;
   return uint(api.NativeGraphicsState());
}

private function appendGraphicsOptions() : void
{
   this._graphicsStart = -1;
   var state:uint = this.graphicsState();
   if((state & 524288) == 0 || this._opts.length == 0 || this._opts[0].id != 10)
   {
      return;
   }
   var original:Array = this._opts;
   this._opts = [];
   var i:int = 0;
   while(i < original.length)
   {
      // The resolution combo replaces the legacy ForceRetina switch.
      if(original[i].id != 33)
      {
         this._opts.push(original[i]);
      }
      i++;
   }
   var russian:Boolean = (state & 262144) != 0;
   var labels:Array = russian ? ["Графика: пресет","Разрешение","Материалы","Тени","Отражения","Глубина резкости"] : ["Graphics: preset","Resolution","Materials","Shadows","Reflections","Depth of field"];
   var automatic:String = russian ? "Авто" : "Auto";
   var options:Array = [russian ? [automatic,"Производит.","Баланс","Высокое","Свой"] : [automatic,"Performance","Balanced","High","Custom"],[automatic,"50%","75%","100%"],russian ? [automatic,"Низкие","Высокие"] : [automatic,"Low","High"]];
   var switches:Array = russian ? [automatic,"Выкл.","Вкл."] : [automatic,"Off","On"];
   this._graphicsStart = this._opts.length;
   i = 0;
   while(i < 6)
   {
      this._opts.push({"id":200 + i,"label":labels[i],"value":state >>> (i * 3) & 7,"options":i < 3 ? options[i] : switches});
      i++;
   }
   this.mc_title.title_lbl.tf.text = String(this._opts.length) + (russian ? ": листайте" : ": scroll");
   this.customize_btn.name_mc.tf.text = russian ? "Графика: после перезапуска" : "Graphics: restart to apply";
   this.customize_btn.mouseEnabled = false;
   this.customize_btn.mouseChildren = false;
   this["customize_btn"].visible = this._graphicsStart >= 0;
   this.appendGraphicsOptions();

private var _graphicsStart:int = -1;

private var _graphicsRefreshing:Boolean = false;
